#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\n' > "$t"
BOOKINGS=$t bash src/remind.sh 2026-01-02 2>&1 | grep -q '^no bookings: 2026-01-02$' || { echo "a day without bookings"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
BOOKINGS=$t bash src/remind.sh 2026-01-02 >/dev/null 2>&1; [ $? = 0 ] || { echo "a day without bookings should exit 0"; fail=1; }
BOOKINGS=$t bash src/remind.sh 2026-01-01 2>/dev/null | grep -qx 'reminder to x: aoi 2026-01-01 10:00-11:00' || { echo "a day with a booking should print its reminder"; fail=1; }
rm -f "$t"; exit $fail

